mapper.select:
SELECT NULL AS id, p.id AS projectId, p.project_name AS projectName, p.status AS projectStatus,
       pm.project_role AS actorProjectRole
FROM lab_project p
LEFT JOIN lab_project_member pm ON pm.project_id=p.id AND pm.user_id=#{userId}
WHERE p.id=#{projectId}

SELECT 
FROM lab_collection_plan cp
JOIN lab_project p ON p.id=cp.project_id
LEFT JOIN lab_project_member pm ON pm.project_id=cp.project_id AND pm.user_id=#{userId}
LEFT JOIN sys_user owner ON owner.id=cp.owner_id
LEFT JOIN lab_experiment_record linked_record ON linked_record.id=cp.linked_experiment_record_id
LEFT JOIN lab_collection_batch latest_batch ON latest_batch.id=(
    SELECT MAX(latest_id.id) FROM lab_collection_batch latest_id WHERE latest_id.plan_id=cp.id
)
WHERE cp.id=#{id}

SELECT COUNT(*) FROM lab_collection_plan
WHERE project_id=#{projectId}
AND status=#{status}
AND source_type=#{sourceType}

SELECT 
FROM lab_collection_plan cp
JOIN lab_project p ON p.id=cp.project_id
LEFT JOIN lab_project_member pm ON pm.project_id=cp.project_id AND pm.user_id=#{userId}
LEFT JOIN sys_user owner ON owner.id=cp.owner_id
LEFT JOIN lab_experiment_record linked_record ON linked_record.id=cp.linked_experiment_record_id
LEFT JOIN lab_collection_batch latest_batch ON latest_batch.id=(
    SELECT MAX(latest_id.id) FROM lab_collection_batch latest_id WHERE latest_id.plan_id=cp.id
)
WHERE cp.project_id=#{projectId}
AND cp.status=#{status}
AND cp.source_type=#{sourceType}
ORDER BY cp.update_time DESC, cp.id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE lab_collection_plan
SET name=#{name}, purpose=#{purpose}, owner_id=#{ownerId},
    metric_definitions_json=#{metricDefinitionsJson},
    linked_experiment_record_id=#{linkedExperimentRecordId}, retention_note=#{retentionNote},
    version=version+1, update_time=#{updateTime}
WHERE id=#{id} AND status='DRAFT' AND version=#{version}

mapper.select:
SELECT 
FROM lab_collection_batch cb
JOIN lab_collection_plan cp ON cp.id=cb.plan_id
JOIN lab_project p ON p.id=cb.project_id
LEFT JOIN lab_project_member pm ON pm.project_id=cb.project_id AND pm.user_id=#{userId}
LEFT JOIN sys_user operator ON operator.id=cb.operator_id
WHERE cb.plan_id=#{planId}
AND cb.status=#{status}
ORDER BY cb.create_time DESC, cb.id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE lab_collection_batch
SET status='COMPLETED', completed_at=#{now}, record_count=#{recordCount},
    rejected_count=#{rejectedCount}, observed_from=#{observedFrom}, observed_to=#{observedTo},
    source_revision_id=#{sourceRevisionId}, completion_reason=#{completionReason}, checksum=#{checksum},
    version=version+1, update_time=#{now}
WHERE id=#{id} AND status='REVIEW_REQUIRED' AND version=#{expectedVersion}

UPDATE lab_collection_batch
SET status=#{toStatus}, completion_reason=#{completionReason}, version=version+1, update_time=#{now}
WHERE id=#{id} AND version=#{expectedVersion}
AND status IN
#{state}

UPDATE lab_collection_batch SET status='PROCESSING', started_at=COALESCE(started_at, #{now}),
    version=version+1, update_time=#{now}
WHERE id=#{id} AND status='CREATED' AND version=#{expectedVersion}

UPDATE lab_data_import SET current_revision_id=#{revisionId}, status='MAPPING_REQUIRED',
    version=version+1, update_time=#{now}
WHERE id=#{id} AND version=#{expectedVersion}

UPDATE lab_data_import SET status='CONFIRMED', current_revision_id=#{revisionId},
    version=version+1, update_time=#{now}
WHERE id=#{id} AND version=#{expectedVersion}

mapper.select:
SELECT cr.id, cr.batch_id AS batchId, cr.data_import_revision_id AS dataImportRevisionId, cr.manual_record_revision_id AS manualRecordRevisionId, cr.source_type AS sourceType, cr.metric_code AS metricCode, cr.value_type AS valueType, cr.value_text AS valueText, cr.unit, cr.observed_at AS observedAt, cr.recorded_by AS recordedBy, cr.method, cr.instrument, cr.raw_row_no AS rawRowNo, cr.quality_status AS qualityStatus, cr.parser_version AS parserVersion, cr.create_time AS createTime FROM lab_collection_record cr
JOIN lab_manual_record mr ON mr.current_revision_id=cr.manual_record_revision_id
WHERE cr.batch_id=#{batchId}
AND cr.data_import_revision_id=#{sourceRevisionId} AND cr.source_type='MANUAL'
AND (cr.observed_at>#{cursorTime} OR (cr.observed_at=#{cursorTime} AND cr.id>#{cursorId}))
ORDER BY cr.observed_at ASC, cr.id ASC LIMIT #{limit}

SELECT er.id AS recordId, er.author_id AS authorId, er.version AS recordVersion,
       er.project_id AS projectId, erv.id AS revisionId, erv.status AS revisionStatus,
       erv.version AS revisionVersion, erv.collection_snapshot_id AS collectionSnapshotId
FROM lab_experiment_record er
JOIN lab_experiment_revision erv ON erv.record_id=er.id AND erv.id=#{revisionId}
WHERE er.id=#{recordId} AND er.author_id=#{userId}

mapper.update:
UPDATE lab_experiment_revision
SET collection_snapshot_id=#{snapshotId}, version=version+1, update_time=#{now}
WHERE record_id=#{recordId} AND id=#{revisionId}
  AND version=#{revisionVersion} AND status='EDITABLE'

mapper.select:
SELECT request_digest AS requestDigest, status, response_json AS responseJson
FROM lab_request_idempotency
WHERE actor_id=#{actorId} AND operation=#{operation} AND idempotency_key=#{key}

mapper.update:
UPDATE lab_request_idempotency
SET status='COMPLETED', response_code=200, response_json=#{responseJson}, update_time=#{now}
WHERE actor_id=#{actorId} AND operation=#{operation} AND idempotency_key=#{key}
